contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        // v1 > v2 > 0 with a large relative gap so the check would fail if enforced.
        require(v2 > 0 && v1 > v2 + 1 && (v1 - v2) * 100 >= v1);

        // Initially enforcement is off for this sender, so enforceTolerance must NOT revert.
        require(!c.enforceLimitsActive(address(this)));
        bool revertedBefore;
        try c.enforceTolerance(v1, v2) { revertedBefore = false; } catch { revertedBefore = true; }

        c.setEnforcement(true);

        bool revertedAfter;
        try c.enforceTolerance(v1, v2) { revertedAfter = false; } catch { revertedAfter = true; }

        assert(
            !revertedBefore &&
            c.enforceLimitsActive(address(this)) &&
            revertedAfter
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, uint8 tolerance) public {
        // v1 > v2 > 0 with a relative gap that violates any tolerance < 100.
        require(v2 > 0 && v1 > v2 + 1 && (v1 - v2) * 100 >= v1);
        require(tolerance < 100);

        // Configure security parameters (configured == false, so this is allowed
        // because assertSuccessfulProposal only requires !configured).
        c.configureSecurityParameters(10, 1000, tolerance);

        // Before enabling enforcement the check must not revert.
        bool revertedBefore;
        try c.enforceTolerance(v1, v2) { revertedBefore = false; } catch { revertedBefore = true; }

        // Enable enforcement for this sender.
        c.setEnforcement(true);

        // Now the violating pair must revert.
        bool revertedAfter;
        try c.enforceTolerance(v1, v2) { revertedAfter = false; } catch { revertedAfter = true; }

        assert(!revertedBefore && revertedAfter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
