    // The contract under test calls back Configurable(msg.sender).configured()
    // (msg.sender == this). Serve that call via the fallback returning true.
    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encode(true);
    }

    function run(uint256 v1, uint256 v2, uint8 tolerance) public {
        // v1 > v2 > 0 with relative gap >= 100%, violating any tolerance < 100.
        require(v2 > 0 && v1 > v2 + 1 && (v1 - v2) * 100 >= v1);
        require(tolerance < 100);

        // configured == false so onlySuccessfulProposal passes.
        c.configureSecurityParameters(10, 1000, tolerance);

        // Before enabling enforcement the check must not revert.
        bool revertedBefore;
        bool okBefore;
        (okBefore, revertedBefore) = tryEnforce(v1, v2);

        // Enable enforcement for this sender.
        c.setEnforcement(true);

        // Now the violating pair must revert.
        bool okAfter;
        bool revertedAfter;
        (okAfter, revertedAfter) = tryEnforce(v1, v2);

        assert(!okBefore && !revertedBefore && okAfter && revertedAfter);
    }
}

