contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable { }

    function run(address a, bool flag, uint256 amount, address asset) public {
        // Precondition: address/params unconstrained; a fresh C is unconfigured.

        // setGoverned (onlySuccessfulProposal passes while configured == false)
        // must store the given flag for the given address.
        address[] memory addrs = new address[](1);
        bool[] memory flags = new bool[](1);
        addrs[0] = a;
        flags[0] = flag;
        c.setGoverned(addrs, flags);
        bool governedA = c.governed(a);

        // configureFlashGovernance (also onlySuccessfulProposal, passes while
        // unconfigured) must store the given asset and amount.
        c.configureFlashGovernance(asset, amount, 7, false);
        (uint256 cfgAmount, , address cfgAsset, ) = c.flashGovernanceConfig();

        // Anyone may end configuration; configured() must then be true.
        c.endConfiguration();
        bool cfg = c.configured();

        assert(governedA == flag && cfgAmount == amount && cfgAsset == asset && cfg);
    }
}

