contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Satisfies Configurable.configured() when c calls back into this contract.
    fallback() external {
        assembly {
            mstore(0, 1)
            return(0, 32)
        }
    }

    function run(uint256 v1, uint256 v2) public {
        // First: with enforcement inactive for this sender, the tolerance check must be skipped.
        c.setEnforcement(false);
        bool revertedInactive;
        try c.enforceTolerance(v1, v2) {
            revertedInactive = false;
        } catch {
            revertedInactive = true;
        }

        (, , , uint256 tolerance) = c.security();

        // Now activate enforcement for this sender and observe the actual behaviour.
        c.setEnforcement(true);
        bool revertedActive;
        try c.enforceTolerance(v1, v2) {
            revertedActive = false;
        } catch {
            revertedActive = true;
        }

        // Expected outcome of the active check, derived from the contract's rule:
        uint256 larger = v1 > v2 ? v1 : v2;
        uint256 smaller = v1 > v2 ? v2 : v1;
        bool expectedRevert = (smaller == 0)
            ? larger > 1
            : ((larger - smaller) * 100 >= tolerance * larger);

        assert(!revertedInactive && revertedActive == expectedRevert);
    }
}

