contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address targetContract, address asset) public payable {
        require(targetContract != address(0) || true);
        // No flash governance decision has ever been created for msg.sender (this contract).
        // Read state before the deciding call (read-only calls may appear in require).
        require(c.pendingFlashDecision(targetContract, address(this)).amount == 0);

        bool reverted;
        try c.withdrawGovernanceAsset(targetContract, asset) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: without a pending (locked, non-zero) flash governance decision,
        // withdrawal must always revert — no asset can be extracted.
        assert(reverted);
    }

    receive() external payable {}
}

