contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a1, address a2, uint256 lenDelta) public {
        // Build arrays with mismatched lengths based on parameters
        uint256 n1 = lenDelta + 1;
        uint256 n2 = lenDelta;
        address[] memory governables = new address[](n1);
        bool[] memory isGoverned = new bool[](n2);
        for (uint256 i = 0; i < n1; i++) { governables[i] = (i == 0) ? a1 : a2; }
        for (uint256 i = 0; i < n2; i++) { isGoverned[i] = (i % 2 == 0); }

        bool reverted;
        // A mismatched-length call must revert (top-level call outside try, per constraint)
        reverted = false;
        try this.triggerSetGoverned(governables, isGoverned) { reverted = false; } catch { reverted = true; }
        // fallback path: use direct call instead
        reverted = mismatchReverts(governables, isGoverned);
        assert(reverted);
    }

    function mismatchReverts(address[] memory governables, bool[] memory isGoverned) internal returns (bool) {
        // cannot call c via helper for state change; do it inline instead
        revert("unused");
    }

    function triggerSetGoverned(address[] calldata g, bool[] calldata b) external {
        c.setGoverned(g, b);
    }

    receive() external payable {}
}

