contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool enforce) public {
        // default changeTolerance is 0, so (2,0) is out of tolerance:
        // v1 > v2, v2 == 0 and v1 > 1 would require "FE1" if enforced.

        // First call with the requested setting.
        c.setEnforcement(enforce);

        bool reverted1;
        bool ok1;
        try c.enforceTolerance(2, 0) { reverted1 = false; ok1 = true; }
        catch { reverted1 = true; ok1 = false; }

        // Toggle to the opposite setting and observe again.
        c.setEnforcement(!enforce);

        bool reverted2;
        try c.enforceTolerance(2, 0) { reverted2 = false; }
        catch { reverted2 = true; }

        // enforceLimitsActive[msg.sender] must equal the last setEnforcement value:
        // enforcement ON -> out-of-tolerance check runs and reverts (caller is not a
        // Configurable, so its configured() call fails); enforcement OFF -> no check,
        // no revert.
        if (enforce) {
            assert(reverted1 && !ok1 && !reverted2);
        } else {
            assert(!reverted1 && ok1 && reverted2);
        }
    }
}

