contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        require(v1 > 0 && v2 > 0);
        require(v1 < 2**248 && v2 < 2**248);

        // Configure tolerance to 99% (allowed, since configured == false, proposal check passes)
        c.configureSecurityParameters(50, 1000, 99);
        // Enable enforcement for this contract as caller
        c.setEnforcement(true);

        bool reverted;
        try c.enforceTolerance(v1, v2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectedRevert = (v1 >= v2)
            ? ((v1 - v2) * 100 >= 99 * v1)
            : ((v2 - v1) * 100 >= 99 * v1);

        assert(reverted == expectedRevert);
    }

    // Configurable(msg.sender).configured() lands here; report true so enforcement applies
    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encode(true);
    }
}

