    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2, int256 i1, int256 i2, bool enforceOn) public payable {
        // default state: enforcement limits are inactive for this caller
        bool r1;
        try c.enforceTolerance(v1, v2) { r1 = false; } catch { r1 = true; }
