        // even after explicitly disabling enforcement, tolerance checks must not revert
        c.setEnforcement(false);
        uint256 big = v1 == type(uint256).max ? type(uint256).max : v1 * 1e18 + 100;
        uint256 small = v2 % 3;
        bool r3;
