            uint8 tolAfter
        ) = c.security();

        assert(
            epochSizeAfter == epochSize &&
            maxAfter == maxGovernanceChangePerEpoch &&
            tolAfter == changeTolerance
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint8 maxGovernanceChangePerEpoch,
        uint256 epochSize,
        uint8 changeTolerance
    ) public {
        require(changeTolerance < 100);

        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);

        (
            uint256 epochSizeAfter,
            uint256 lastActAfter,
            uint8 maxAfter,
            uint8 tolAfter
        ) = c.security();

        assert(
            epochSizeAfter == epochSize &&
            maxAfter == maxGovernanceChangePerEpoch &&
            tolAfter == changeTolerance &&
            lastActAfter == 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v, uint256 other) public {
        // enable enforcement for this contract as caller
        c.setEnforcement(true);

        // equal values must always satisfy the tolerance check
        bool revertedEqual;
        try c.enforceTolerance(v, v) { revertedEqual = false; } catch { revertedEqual = true; }

        // setEnforcement must have taken effect for this caller: toggling to false
        // must also let enforceTolerance pass regardless of values
        c.setEnforcement(false);
        bool revertedOff;
        try c.enforceTolerance(v, other) { revertedOff = false; } catch { revertedOff = true; }

        assert(!revertedEqual && !revertedOff);
    }

    fallback() external {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        // ensure enforcement is explicitly disabled for this caller
        c.setEnforcement(false);

        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }

        // even extreme comparisons must pass when enforcement is off
        bool revertedExtreme;
        try c.enforceTolerance(v1 + 1, 0) { revertedExtreme = false; } catch { revertedExtreme = true; }

        assert(!reverted && !revertedExtreme);
    }

    fallback() external {}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 v1, uint256 v2) public {
        require(v1 > 1 && v2 > 1);
        // enable enforcement for this caller (msg.sender on c is this test contract)
        c.setEnforcement(true);
        // fresh deployment: changeTolerance is 0, so any change is disallowed
        bool reverted;
        try c.enforceTolerance(v1, v2) { reverted = false; } catch { reverted = true; }
        assert(reverted == (v1 != v2));
    }

    fallback() external returns (bytes memory) {
        // makes Configurable(address(this)).configured() return true
        return abi.encode(true);
    }

    receive() external payable {}
}
